def _file_id(self, filename, add=False):
    """Get the file id for `filename`.

    If filename is not in the database yet, add it if `add` is True.
    If `add` is not True, return None.
    """
    if filename not in self._file_map:
        if add:
            with self._connect() as con:
                try:
                    cur = con.execute("insert or replace into file (path) values (?)", (filename,))
                    self._file_map[filename] = cur.lastrowid
                except UnicodeEncodeError:
                    # The filename contains characters that can't be encoded
                    # as UTF-8 (e.g., surrogate characters). Skip this file.
                    if self._warn:
                        self._warn(
                            "Couldn't measure file %r, it has a filename that can't be "
                            "encoded with the UTF-8 codec. The most common cause of this "
                            "error is code that creates files with surrogate characters "
                            "in their names. You can use the [report] omit option to skip "
                            "this file." % (filename,)
                        )
                    # Mark this file as skipped so we don't try again
                    self._file_map[filename] = None
    return self._file_map.get(filename)

def add_lines(self, line_data):
    """Add measured line data.

    `line_data` is a dictionary mapping file names to dictionaries::

        { filename: { lineno: None, ... }, ...}

    """
    if self._debug.should('dataop'):
        self._debug.write("Adding lines: %d files, %d lines total" % (
            len(line_data), sum(len(lines) for lines in line_data.values())
        ))
    self._start_using()
    self._choose_lines_or_arcs(lines=True)
    if not line_data:
        return
    with self._connect() as con:
        self._set_context_id()
        for filename, linenos in iitems(line_data):
            file_id = self._file_id(filename, add=True)
            if file_id is None:
                # The file couldn't be added (e.g., unencodable filename)
                continue
            linemap = nums_to_numbits(linenos)
            query = "select numbits from line_bits where file_id = ? and context_id = ?"
            existing = list(con.execute(query, (file_id, self._current_context_id)))
            if existing:
                linemap = numbits_union(linemap, existing[0][0])

            con.execute(
                "insert or replace into line_bits "
                " (file_id, context_id, numbits) values (?, ?, ?)",
                (file_id, self._current_context_id, linemap),
            )
